+	}
+	if resp.Prompts[0] != "first prompt" {
+		t.Errorf("expected first prompt, got %q", resp.Prompts[0])
+	}
+	if resp.Prompts[1] != "second prompt" {
+		t.Errorf("expected second prompt, got %q", resp.Prompts[1])
+	}
+}
